uniform float uZ, uHB, uRes, uPuff;
uniform float uPr[8];
out vec4 o;
float smin(float a, float b, float k){ float h = max(k - abs(a - b), 0.0) / k; return min(a, b) - h*h*k*0.25; }
float smax(float a, float b, float k){ return -smin(-a, -b, k); }
float sdBall(vec3 p, float r){ return length(p) - r; }
float sdBox(vec3 p, vec3 b, float r){ vec3 q = abs(p) - b + r; return length(max(q, 0.0)) + min(max(q.x, max(q.y, q.z)), 0.0) - r; }
#define side uPr[0]
#define CLIP (length(p) - 1.300)
#define SHELL (0.0)
float f(vec3 q){ const float ph = 1.618034; vec3 a = q*q; return side * (4.0*(ph*ph*a.x - a.y)*(ph*ph*a.y - a.z)*(ph*ph*a.z - a.x) - (1.0 + 2.0*ph)*(a.x + a.y + a.z - 1.0)*(a.x + a.y + a.z - 1.0)); }
float raw(vec3 p){ return f(p * 1.9000); }

void main(){
  vec3 p = (vec3(gl_FragCoord.xy / uRes, uZ) * 2.0 - 1.0) * uHB;
  const float e = 0.0007;
  const vec2 k = vec2(1.0, -1.0);
  vec3 x = p;
  float v0 = 0.0, last = 1.0;
  for (int i = 0; i < 8; i++){
    float a = raw(x + e*k.xyy), b = raw(x + e*k.yyx), c = raw(x + e*k.yxy), d = raw(x + e*k.xxx);
    float fv = 0.25 * (a + b + c + d);
    vec3 g = (k.xyy*a + k.yyx*b + k.yxy*c + k.xxx*d) / (4.0 * e);
    if (i == 0) v0 = fv;
    vec3 st = g * (fv / max(dot(g, g), 1e-12));
    last = length(st);
    if (last > 0.12) st *= 0.12 / last;                 // never leap: far from the surface the gradient misleads
    x -= st;
    if (last < 2e-5) break;
  }
  float dist = length(x - p);
  dist *= mix(1.0, 0.7, smoothstep(0.06, 0.2, dist));   // a long walk may not have ended at the nearest point: stay cautious
  float sd = (v0 < 0.0 ? -dist : dist) - uPuff;          // uPuff swells (or shrinks) the whole surface evenly
  float w = SHELL;
  if (w > 0.0) sd = abs(sd) - w;
  o = vec4(clamp(smax(sd, CLIP, 0.03), -1.0, 1.0), 0.0, 0.0, 1.0);
}

